using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class LandSurveyTests
{
 static readonly EntityId Site=new("site:castle"),Owner=new("org:oda");
 internal static WorldSession Start()=>HouseholdCourtTests.Start();
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static SurveyInput Input(WorldSession s,SurveyAction action,EntityId? reference=null,LandTaxRate rate=LandTaxRate.Ordinary)=>new(new("request:survey/"+s.Revision),action,Owner,Site,reference,rate);
 [Fact]
 public void UnansweredVillagePetitionStopsWorksUntilRiceIsActuallyDelivered()
 {
     var s=Start();Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,rate:LandTaxRate.Heavy),s.Revision));
     NewGameWorldTests.At(s,37*86400);
     Assert.Contains("人出を断って",s.VillageView()!.Reaction);
     var work=new WorksInput(new("request:works-after-petition"),Site,WorksKind.Agriculture);
     Assert.Equal(ResultCode.NotAvailable,s.StartPublicWork(work,s.Revision).Code);
     var relief=new CommunityInput(new("request:relief-after-petition"),Site,EconomyAction.RelieveVillage,CommunityEconomy.Population);
     Good(s.ManageCommunity(relief,s.PlayerControl,s.Revision));
     var bytes=ContractJson.Write(s.DiagnosticSnapshot());
     var resumed=new WorldSession(ContractJson.Read<ContractWorld>(bytes));
     foreach(var run in new[]{s,resumed})Good(run.StartPublicWork(work,run.Revision));
     Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(resumed.DiagnosticSnapshot()));
 }
 [Fact]
 public void TaxPetitionKeepsItsOriginalDecreeAfterEffectiveRemission()
 {
     var s=Start();
     var heavy=Input(s,SurveyAction.PostRate,rate:LandTaxRate.Heavy);
     Good(s.ManageLandSurvey(heavy,s.Revision));
     CommunityNotice[] Papers()=>s.DiagnosticSnapshot().Communities!.Notices.Where(n=>n.Site==Site && n.Petition?.TaxDecree!=null).ToArray();
     Assert.Empty(Papers());
     NewGameWorldTests.At(s,7*86400);
     var first=Assert.Single(Papers());Assert.Equal(heavy.Id,first.Petition!.TaxDecree);
     Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,rate:LandTaxRate.Gentle),s.Revision));
     NewGameWorldTests.At(s,40*86400);
     Assert.Equal(LandTaxRate.Gentle,LandSurvey.EffectiveDecree(s.DiagnosticSnapshot(),Site,s.Seconds)!.Input.Rate);
     Assert.Equal(first,Assert.Single(Papers()));
     var bytes=ContractJson.Write(s.DiagnosticSnapshot());
     Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));
 }
 [Fact]public void MeasurementHasActualCostsLaborAndTimeButNoInstantKnowledge(){var s=Start();long cash=s.HouseTreasuryView()!.HouseCash,rice=s.CommunityEconomyView()!.Accounts.HouseRice;var i=Input(s,SurveyAction.Measurement);Good(s.ManageLandSurvey(i,s.Revision));Assert.Equal(cash-30,s.HouseTreasuryView()!.HouseCash);Assert.Equal(rice-100,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(90,s.CommunityEconomyView()!.Accounts.Workforce);Assert.Empty(LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.ManageLandSurvey(Input(s,SurveyAction.ReadBook,i.Id),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageLandSurvey(Input(s,SurveyAction.Statement),s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.ManageLandSurvey(i,s.Revision).Code);NewGameWorldTests.At(s,7*86400);Assert.Empty(LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl));Good(s.ManageLandSurvey(Input(s,SurveyAction.ReadBook,i.Id),s.Revision));var b=Assert.Single(LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl));Assert.True(b.Measured);Assert.Equal(20000,b.Basis);Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);}
 [Fact]public void StatementRemainsAVillagerEstimateRatherThanAFraudJudgment(){var s=Start();var i=Input(s,SurveyAction.Statement);Good(s.ManageLandSurvey(i,s.Revision));NewGameWorldTests.At(s,2*86400);Good(s.ManageLandSurvey(Input(s,SurveyAction.ReadBook,i.Id),s.Revision));var b=LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl).Single();Assert.False(b.Measured);Assert.Contains("不正の証拠ではない",b.Description);Assert.InRange(b.Basis,18000,22000);}
 [Fact]public void TaxStartsAfterPostedEffectiveDateAndNeverRewritesPastAssessment(){var s=Start();Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,rate:LandTaxRate.Heavy),s.Revision));long rice=s.CommunityEconomyView()!.Accounts.HouseRice;Assert.Null(LandSurvey.EffectiveDecree(s.DiagnosticSnapshot(),Site,s.Seconds));NewGameWorldTests.At(s,7*86400);Assert.Equal(LandTaxRate.Heavy,LandSurvey.EffectiveDecree(s.DiagnosticSnapshot(),Site,s.Seconds)!.Input.Rate);Assert.Equal(rice,s.CommunityEconomyView()!.Accounts.HouseRice);long autumn=(new DateOnly(1560,10,1).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;NewGameWorldTests.At(s,autumn);var a=s.CommunityEconomyView()!.Accounts;Assert.Equal(a.Harvested*40/100,a.Assessed);Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,rate:LandTaxRate.Gentle),s.Revision));NewGameWorldTests.At(s,autumn+7*86400);Assert.Equal(a.Assessed,s.CommunityEconomyView()!.Accounts.Assessed);Good(s.ManageCommunity(new(new("request:survey-actual-levy"),Site,EconomyAction.CollectLevy,1),s.PlayerControl,s.Revision));Assert.Equal(a.HouseRice+1,s.CommunityEconomyView()!.Accounts.HouseRice);}
 [Fact]public void AnUnreadMeasurementCannotBecomeTheBasisForAPostedTax(){var s=Start();var i=Input(s,SurveyAction.Measurement);Good(s.ManageLandSurvey(i,s.Revision));NewGameWorldTests.At(s,7*86400);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageLandSurvey(Input(s,SurveyAction.PostRate,i.Id,LandTaxRate.Heavy),s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Good(s.ManageLandSurvey(Input(s,SurveyAction.ReadBook,i.Id),s.Revision));Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,i.Id,LandTaxRate.Ordinary),s.Revision));}
 static void Npc(WorldSession s,Action<ContractWorld> action)=>typeof(WorldSession).GetMethod("Change",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.Invoke(s,[action,null]);
 [Fact]public void AgentReportMustPhysicallyArriveAndBeOpenedBeforeHeadKnowsTheBook(){var s=StandingAdministrationTests.Appointed();var agent=HouseholdCourtTests.Retainer;var job=new EntityId("request:npc-survey");Npc(s,w=>LandSurvey.Execute(w,new(job,SurveyAction.Measurement,Owner,Site),agent));NewGameWorldTests.At(s,8*86400);var paper=s.DiagnosticSnapshot().Surveys!.Papers.Single(p=>p.Sender==agent);Assert.Empty(LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl));Good(s.Open(s.PlayerControl,new(paper.Id),s.Revision));Assert.Contains(LandSurvey.KnownBooks(s.DiagnosticSnapshot(),s.PlayerControl),b=>b.Job==job);}
 [Fact]public void RealMidSurveySaveHasSameBookResourceAndKnowledgeFuture(){var s=Start();var i=Input(s,SurveyAction.Measurement);Good(s.ManageLandSurvey(i,s.Revision));NewGameWorldTests.At(s,3*86400);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"survey-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"mid",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("mid"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current}){NewGameWorldTests.At(x,7*86400);Good(x.ManageLandSurvey(Input(x,SurveyAction.ReadBook,i.Id),x.Revision));Good(x.ManageLandSurvey(Input(x,SurveyAction.PostRate,i.Id,LandTaxRate.Gentle),x.Revision));}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void HeavyPostedTaxLeavesAReasonForReducedVillageCooperation(){var s=Start();Good(s.ManageLandSurvey(Input(s,SurveyAction.PostRate,rate:LandTaxRate.Heavy),s.Revision));NewGameWorldTests.At(s,7*86400+150*86400);Assert.Contains("年貢",s.VillageView()!.Reaction);Assert.Equal(ResultCode.NotAvailable,s.StartPublicWork(new(new("request:tax-pressured-work"),Site,WorksKind.Agriculture),s.Revision).Code);}
 [Fact]public void ExistingSaveRemainsByteExactAndDoesNotGainATaxModule(){var w=Start().DiagnosticSnapshot();var b=ContractJson.Write(w);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));w.Surveys=new(1,LandSurvey.Policy,[],[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

 [Fact]public void LaterNpcCandidateCannotSpendTheSameBeforeTransactionBalanceAgain(){var s=CraftTradeTests.Start();var site=new EntityId("site:sakai");var owner=new EntityId("created:port-house");Good(s.ManageHouseTreasury(new(new("request:sequence-budget"),TreasuryAction.SetBudget,site,Amount:1000),s.PlayerControl,s.Revision));long ricePrice=s.RegionalTradeView()!.BuyPrice;long riceQuantity=(s.HouseTreasuryView()!.HouseCash-51)/ricePrice;Good(s.ManageHouseTreasury(new(new("request:sequence-rice"),TreasuryAction.Buy,site,Quantity:riceQuantity),s.PlayerControl,s.Revision));long change=s.HouseTreasuryView()!.HouseCash-51;if(change>0)Good(s.ManageCraft(new(new("request:sequence-stone"),CraftAction.Buy,owner,site,Good:"rough-stone",Quantity:change),s.Revision));Assert.Equal(51,s.HouseTreasuryView()!.HouseCash);bool accepted=true;Npc(s,w=>{PublicWorks.Execute(w,new(new("request:sequence-farm"),site,WorksKind.Agriculture),s.PlayerControl);var type=typeof(WorldSession).Assembly.GetType("HakutaiKagami.Core.Contracts.TransactionalWorld")!;accepted=(bool)type.GetMethod("TryApply",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,[w,new Action<ContractWorld>(c=>CraftTrade.Execute(c,new(new("request:sequence-iron"),CraftAction.Buy,owner,site,Good:"iron"),s.PlayerControl))])!;});Assert.False(accepted);Assert.Equal(1,s.HouseTreasuryView()!.HouseCash);Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),owner,site,"iron"));Assert.DoesNotContain(s.DiagnosticSnapshot().Crafts!.Entries,e=>e.Input.Id==new EntityId("request:sequence-iron"));ContractValidation.Validate(s.DiagnosticSnapshot());}
 [Fact]public void LocalSalePaysFromMerchantAndCannotSellSameStockTwice(){var s=CraftTradeTests.Start();var site=new EntityId("site:sakai");var owner=new EntityId("created:port-house");Good(s.ManageCraft(new(new("request:sale-buy"),CraftAction.Buy,owner,site,Good:"iron",Quantity:2),s.Revision));long cash=s.HouseTreasuryView()!.HouseCash;long merchant=CraftTrade.MerchantCash(s.DiagnosticSnapshot(),site);Good(s.ManageCraft(new(new("request:sale-sell"),CraftAction.Sell,owner,site,Good:"iron",Quantity:2),s.Revision));long gain=s.HouseTreasuryView()!.HouseCash-cash;Assert.True(gain>0);Assert.Equal(merchant-gain,CraftTrade.MerchantCash(s.DiagnosticSnapshot(),site));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),owner,site,"iron"));Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(new(new("request:sale-again"),CraftAction.Sell,owner,site,Good:"iron",Quantity:2),s.Revision).Code);}
}
